-- Source: MotherDuck thyroid_canonical_publication_v1_0.manuscript_workspace.canonical_path_malignant_events_v1_size_flag
-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.canonical_path_malignant_events_v1_size_flag AS WITH surg AS (SELECT research_id, surgery_date, count_star() AS n_tumors, max(size_greatest_dimension_cm) AS max_greatest_cm, any_value(tumor_size_cm_per_surgery) AS per_surgery_cm FROM main.canonical_path_malignant_events_v1 GROUP BY research_id, surgery_date)SELECT e.*, s.n_tumors, s.max_greatest_cm, ((s.n_tumors = 1) AND (s.max_greatest_cm IS NOT NULL) AND (s.per_surgery_cm IS NOT NULL) AND (abs((s.per_surgery_cm - s.max_greatest_cm)) > 0.1)) AS size_single_tumor_mismatch_flag, (s.per_surgery_cm < (s.max_greatest_cm - 0.1)) AS size_per_surgery_understates_flag, (s.per_surgery_cm > (s.max_greatest_cm + 0.1)) AS size_per_surgery_overstates_flag, (((s.n_tumors = 1) AND (s.max_greatest_cm IS NOT NULL) AND (s.per_surgery_cm IS NOT NULL) AND (abs((s.per_surgery_cm - s.max_greatest_cm)) > 0.1)) OR (s.per_surgery_cm < (s.max_greatest_cm - 0.1)) OR (s.per_surgery_cm > (s.max_greatest_cm + 0.1))) AS size_disagreement_any_flag FROM main.canonical_path_malignant_events_v1 AS e LEFT JOIN surg AS s ON (((e.research_id = s.research_id) AND (e.surgery_date = s.surgery_date)));
